CREATE TABLE community_comment (id BIGINT NOT NULL AUTO_INCREMENT,post_id BIGINT NOT NULL,author_id BIGINT NOT NULL,content TEXT NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'published',deleted_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),KEY idx_community_comment_post(post_id,status,created_at,id),KEY idx_community_comment_author(author_id,created_at DESC,id DESC),CONSTRAINT ck_community_comment_status CHECK(status IN ('published','hidden','deleted')),CONSTRAINT ck_community_comment_deleted CHECK((status='deleted')=(deleted_at IS NOT NULL)),CONSTRAINT ck_community_comment_content CHECK(CHAR_LENGTH(TRIM(content)) BETWEEN 1 AND 3000),CONSTRAINT fk_community_comment_post FOREIGN KEY(post_id) REFERENCES community_post(id) ON DELETE RESTRICT,CONSTRAINT fk_community_comment_author FOREIGN KEY(author_id) REFERENCES user_account(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
